import{_ as s,a0 as l,w as d,s as p,ao as o,I as r,a1 as i,A as n,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const O=JSON.parse('{"title":"EndeavourOS Artemis 22.06 发布，带来更好的 ARM 支持 | LCTT x X-CMD","titleTemplate":false,"description":"EndeavourOS Artemis 22.06 发布，带来更好的 ARM 支持 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"EndeavourOS Artemis 22.06 发布，带来更好的 ARM 支持 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"EndeavourOS Artemis 22.06 发布，带来更好的 ARM 支持 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230711.0 ⭐️ EndeavourOS Artemis Released with Better ARM Support and Updates","title":"EndeavourOS Artemis 22.06 发布，带来更好的 ARM 支持","tag":"202307","desc":""},"relativePath":"202307/20230711.0 ⭐️ EndeavourOS Artemis Released with Better ARM Support and Updates.md","filePath":"[post].md"}'),u={name:"202307/20230711.0 ⭐️ EndeavourOS Artemis Released with Better ARM Support and Updates.md"};function m(A,e,f,S,v,b){const a=l("Link");return d(),p("div",null,[e[23]||(e[23]=o('<h1 id="endeavouros-artemis-22-06-发布-带来更好的-arm-支持" tabindex="-1">EndeavourOS Artemis 22.06 发布，带来更好的 ARM 支持 <a class="header-anchor" href="#endeavouros-artemis-22-06-发布-带来更好的-arm-支持" aria-label="Permalink to “EndeavourOS Artemis 22.06 发布，带来更好的 ARM 支持”">​</a></h1><blockquote><p>EndeavourOS 团队发布了 6 月份的 22.06 版本（“Artemis”），带来了更好的 ARM 支持，最新内核等功能。我们在本文中总结发布内容。</p></blockquote><p><img src="https://debugpointnews.com/wp-content/uploads/2022/06/EndeavourOS-Artemis-22.06-Desktop-Xfce.jpg" alt="EndeavourOS Artemis 22.06 桌面（Xfce）"></p><h3 id="endeavouros-artemis-发布-22-06" tabindex="-1">EndeavourOS Artemis 发布：22.06 <a class="header-anchor" href="#endeavouros-artemis-发布-22-06" aria-label="Permalink to “EndeavourOS Artemis 发布：22.06”">​</a></h3>',4)),r("p",null,[i(a,{href:"https://debugpointnews.com/tag/endeavouros/"},{default:n(()=>[...e[0]||(e[0]=[t("EndeavourOS",-1)])]),_:1}),e[1]||(e[1]=t(" Artemis 版本（22.06）以 NASA 即将进行的月球任务 “",-1)),e[2]||(e[2]=r("ruby",null,[t("阿尔忒弥斯"),r("rt",null,"Artemis")],-1)),e[3]||(e[3]=t("” 命名，为这个出色的 Linux 发行版带来了定期的 Arch Linux 更新。",-1))]),e[24]||(e[24]=o('<h4 id="arm-更新" tabindex="-1">ARM 更新 <a class="header-anchor" href="#arm-更新" aria-label="Permalink to “ARM 更新”">​</a></h4><p>EndeavourOS 的 ARM 版本首次发布于 2020 年，成为了该团队的长期目标。这个目标是为用户提供一种稳定的基于 Arch Linux 的 ARM 变体发行版，注重 “友好性” 和 “功能性”。在 22.06 中，ARM ISO 被称为 “更接近主要发布版本”。</p><p>这次月度更新中的重要改变是在 ARM 安装过程中引入了 Calamares 安装程序。此外，ARM 安装的快捷方式被放置在其标志性的 “<ruby>欢迎<rt>Welcome</rt></ruby>” 应用程序中。</p><p><img src="https://debugpointnews.com/wp-content/uploads/2022/06/EndeavourOS-Artemis-brings-better-accessibility-for-ARM.jpg" alt="EndeavourOS Artemis 提供更好的 ARM 可访问性"></p><p>然而，ARM 中的 Calamares 安装程序仍处于 BETA 阶段。这意味着在安装时需要谨慎，目前支持的设备有：Odroid N2/N2+ 和树莓派。</p><p>此外，ARM 安装中的桌面环境和软件包已经更加精细调整以与上游同步。因此，你可以在树莓派设备上获得最新和最优秀的软件。</p><h4 id="其他变化" tabindex="-1">其他变化 <a class="header-anchor" href="#其他变化" aria-label="Permalink to “其他变化”">​</a></h4><p>除了上述变更外，EndeavourOS 22.06 版本还带来了 Linux 内核 5.18.5。截至撰写本文时，Linux 内核 5.19 尚未发布。因此，在这个出色发行版的下一个 ISO 更新中可能会包含该版本。</p><p>此次发布中的其他值得注意的变更包括将 pipewire-media-session 替换为 wireplumber，并对 Xfce 离线安装进行了代码清理。此外，著名的 Budgie 控制中心现在在该发行版的 Budgie 版本中已经可用，以提供原生 Budgie 的体验。</p><p>总结起来，这个版本的主要变更如下：</p><ul><li>ARM ISO 更接近主要发布版本</li><li>ARM 安装中可使用 Calamares 安装程序</li><li>Linux 内核 5.18.5</li><li>Xfce 4.16 版本（旗舰版）进行了安装程序代码清理</li><li>Budgie 控制中心现在在 EndeavourOS 存储库中可用</li><li>在在线安装之前提供更好的密钥环同步问题控制</li><li>添加了降级软件包的支持 - eos-downgrade</li><li>Firefox 101.x</li></ul><h3 id="简单测评" tabindex="-1">简单测评 <a class="header-anchor" href="#简单测评" aria-label="Permalink to “简单测评”">​</a></h3><p>我们在虚拟机环境中测试了这个发行版。Xfce 离线安装的下载大小为 1.8 GB，并且安装过程很顺利。镜像下周速度非常快。</p><p>首先，<ruby>立付<rt>Live</rt></ruby> 桌面可以让你启动安装 - 支持离线和在线两种。离线安装将安装 Xfce 桌面环境。此外，如果你有互联网连接，可以使用在线安装选项安装其他桌面环境和窗口管理器。</p><p>其次，通过 Calamares 安装非常顺利。尽管最近发布了 “archinstall”，它使 Arch Linux 的安装变得非常容易。我必须说，EndeavourOS 正在成为 Arch Linux 世界中的 “Linux Mint”。</p><p>安装完成后，桌面将通过 “欢迎” 应用程序向你表示欢迎。如果你是新用户，“欢迎” 应用程序为你提供一个入口点，用于执行各种桌面任务。</p><p>性能经过了良好优化。在空闲状态下，此版本在 Xfce 桌面上使用 2% 到 3% 的 CPU 和约 900 MB 的 RAM。这是一个不错的指标。</p><p><img src="https://debugpointnews.com/wp-content/uploads/2022/06/EndeavourOS-Artemis-Performance.jpg" alt="EndeavourOS Artemis 性能"></p><p>此外，如果你打开更多应用程序进行工作，资源消耗可能会增加。</p><p>最后，EndeavourOS Artemis Xfce 版默认安装占用 4.2 GB 的磁盘空间。</p><h3 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to “下载”">​</a></h3><p>你可以在此页面下载官方发布版本，其中包含镜像和种子文件。</p>',22)),r("blockquote",null,[r("p",null,[r("strong",null,[i(a,{href:"https://endeavouros.com/latest-release/"},{default:n(()=>[...e[4]||(e[4]=[t("下载 EndeavourOS",-1)])]),_:1})])])]),r("p",null,[e[6]||(e[6]=t("参考自官方 ",-1)),i(a,{href:"https://endeavouros.com/news/artemis-is-launched/"},{default:n(()=>[...e[5]||(e[5]=[t("发布公告",-1)])]),_:1}),e[7]||(e[7]=t("。",-1))]),e[25]||(e[25]=r("hr",null,null,-1)),r("p",null,[e[9]||(e[9]=t("via: ",-1)),i(a,{href:"https://debugpointnews.com/endeavouros-artemis/"},{default:n(()=>[...e[8]||(e[8]=[t("https://debugpointnews.com/endeavouros-artemis/",-1)])]),_:1})]),r("p",null,[e[14]||(e[14]=t("作者：",-1)),i(a,{href:"https://debugpointnews.com/author/dpicubegmail-com/"},{default:n(()=>[...e[10]||(e[10]=[t("arindam",-1)])]),_:1}),e[15]||(e[15]=t(" 选题：",-1)),i(a,{href:"https://github.com/lkxed/"},{default:n(()=>[...e[11]||(e[11]=[t("lkxed",-1)])]),_:1}),e[16]||(e[16]=t(" 译者：",-1)),i(a,{href:"https://github.com/%E8%AF%91%E8%80%85ID"},{default:n(()=>[...e[12]||(e[12]=[t("译者ID",-1)])]),_:1}),e[17]||(e[17]=t(" 校对：",-1)),i(a,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:n(()=>[...e[13]||(e[13]=[t("校对者ID",-1)])]),_:1})]),r("p",null,[e[20]||(e[20]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[18]||(e[18]=[t("LCTT",-1)])]),_:1}),e[21]||(e[21]=t(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...e[19]||(e[19]=[t("Linux中国",-1)])]),_:1}),e[22]||(e[22]=t(" 荣誉推出",-1))])])}cons